-- CHAMBA 010 — Parte 1/4: tablas + índices + jobs.category → TEXT-- Ejecuta SOLO este bloque en Supabase → SQL Editor → Run-- Si vuelve a dar timeout, espera 1 min y ejecuta de nuevo (es idempotente).SET statement_timeout = '180s';CREATE TABLE IF NOT EXISTS service_categories (  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),  slug        TEXT NOT NULL UNIQUE,  name        TEXT NOT NULL,  icon        TEXT NOT NULL DEFAULT '📋',  image_url   TEXT,  sort_order  INT NOT NULL DEFAULT 0,  is_active   BOOLEAN NOT NULL DEFAULT TRUE,  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),  updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE TABLE IF NOT EXISTS service_types (  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),  category_id      UUID NOT NULL REFERENCES service_categories(id) ON DELETE CASCADE,  slug             TEXT NOT NULL,  name             TEXT NOT NULL,  description      TEXT,  icon             TEXT NOT NULL DEFAULT '🔧',  image_url        TEXT,  suggested_price  NUMERIC(12,2) NOT NULL DEFAULT 0,  min_price_ratio  NUMERIC(4,2) NOT NULL DEFAULT 0.5,  sort_order       INT NOT NULL DEFAULT 0,  is_active        BOOLEAN NOT NULL DEFAULT TRUE,  created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),  updated_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),  UNIQUE (category_id, slug));CREATE INDEX IF NOT EXISTS idx_service_types_category ON service_types(category_id);CREATE INDEX IF NOT EXISTS idx_service_types_slug ON service_types(slug);-- jobs.category: enum → TEXT (puede tardar si hay muchos jobs)DO $$BEGIN  IF EXISTS (    SELECT 1 FROM information_schema.columns    WHERE table_schema = 'public'      AND table_name = 'jobs'      AND column_name = 'category'      AND udt_name = 'job_category'  ) THEN    ALTER TABLE jobs ALTER COLUMN category TYPE TEXT USING category::TEXT;  END IF;END $$;